import{b as o,O as a,g as r,j as l}from"./chunks/framework.DcaUmd3X.js";const i="/assets/image-1.DtjuOkwA.webp",e="/assets/image.CSIeGkLf.webp",c=JSON.parse('{"title":"探索式测试（下）—— 技能与实战","description":"","frontmatter":{},"headers":[],"relativePath":"testing/methodology/exploratory-testing-2/index.md","filePath":"测试理论与实践/3.测试方法体系/09.探索式测试（下）.md","lastUpdated":1783947942000}'),n={name:"testing/methodology/exploratory-testing-2/index.md"};function s(u,t,d,h,q,g){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="探索式测试-下-——-技能与实战" tabindex="-1">探索式测试（下）—— 技能与实战 <a class="header-anchor" href="#探索式测试-下-——-技能与实战" aria-label="Permalink to &quot;探索式测试（下）—— 技能与实战&quot;">​</a></h1><blockquote><p>上一章讲了探索式测试的&quot;头脑&quot;——章程、会话、启发法。这一章讲&quot;手脚&quot;——五个核心技能，以及怎么把这些技能用在三种典型场景里。</p></blockquote><h2 id="技能一-观察——看见真正发生的事" tabindex="-1">技能一：观察——看见真正发生的事 <a class="header-anchor" href="#技能一-观察——看见真正发生的事" aria-label="Permalink to &quot;技能一：观察——看见真正发生的事&quot;">​</a></h2><p>&quot;看见&quot;听上去没什么了不起。但在测试中，<strong>真正观察到系统行为</strong>比你以为的难得多。</p><h3 id="常见的观察陷阱" tabindex="-1">常见的观察陷阱 <a class="header-anchor" href="#常见的观察陷阱" aria-label="Permalink to &quot;常见的观察陷阱&quot;">​</a></h3><ul><li>你点了一个按钮，页面刷新了——你没注意到地址栏多了一个 <code>?debug=true</code></li><li>你提交了一个表单，看起来成功了——你没看控制台，那里有一条 500 错误日志</li><li>你测了 Chrome，一切正常——你没想起来再测一下 Safari</li></ul><p>观察不是&quot;看界面&quot;，是<strong>关注一切可见的信号</strong>：界面变化、控制台输出、网络请求、日志文件、数据库记录、系统资源（CPU、内存）。</p><h3 id="提高可测试性" tabindex="-1">提高可测试性 <a class="header-anchor" href="#提高可测试性" aria-label="Permalink to &quot;提高可测试性&quot;">​</a></h3><p>有些系统行为天生不可见——比如缓存是否命中、消息队列是否有堆积。这时候你需要<strong>提高可测试性</strong>：让不可见的东西变得可见。</p><ul><li>打开日志级别到 DEBUG</li><li>在关键位置加临时日志输出</li><li>用代理工具（Charles、Fiddler）抓包看请求细节</li><li>用数据库客户端直接查数据有没有写对</li></ul><p><strong>一个实用心法</strong>：当你发现一个现象解释不了时，不要跳过。问自己&quot;这背后发生了什么？&quot;——然后想办法让背后的东西可见。</p><h2 id="技能二-变量——找出会变化的事物" tabindex="-1">技能二：变量——找出会变化的事物 <a class="header-anchor" href="#技能二-变量——找出会变化的事物" aria-label="Permalink to &quot;技能二：变量——找出会变化的事物&quot;">​</a></h2><p>变量就是<strong>任何会改变的东西</strong>。识别变量是探索式测试最核心的分析技能。</p><h3 id="显性变量-vs-微妙变量" tabindex="-1">显性变量 vs 微妙变量 <a class="header-anchor" href="#显性变量-vs-微妙变量" aria-label="Permalink to &quot;显性变量 vs 微妙变量&quot;">​</a></h3><p>显性变量一眼能看到：输入框的值、下拉框的选项、网络状态（在线/离线）、屏幕尺寸。</p><p>微妙变量容易被忽略，但它们往往是 bug 的温床：</p><ul><li><strong>操作速度</strong>：快速双击一个按钮 vs 慢速单击——触发的是同一个事件吗？</li><li><strong>数据量</strong>：10 条记录的列表 vs 10,000 条——排序、筛选、分页都正常吗？</li><li><strong>时间点</strong>：凌晨 00:00:00——跨天的数据统计对吗？定时任务跑了吗？</li><li><strong>编码和字符集</strong>：中文、日文、emoji、从右向左的文字——都能正常显示和存储吗？</li><li><strong>用户角色</strong>：管理员看到的和普通用户看到的——权限边界有没有缝隙？</li></ul><h3 id="一个识别变量的练习" tabindex="-1">一个识别变量的练习 <a class="header-anchor" href="#一个识别变量的练习" aria-label="Permalink to &quot;一个识别变量的练习&quot;">​</a></h3><p>随便打开一个页面，盯着它看 60 秒，问自己：<strong>这个页面上有什么东西是会变化的？</strong></p><p>然后列出：</p><ol><li>用户输入的数据</li><li>网络响应回来的数据</li><li>当前时间、时区</li><li>屏幕尺寸、设备类型</li><li>用户登录状态</li><li>这个页面在不同系统语言下的表现</li></ol><p>你列的越多，后面测试的方向就越丰富。</p><h2 id="技能三-评估——判断结果对不对" tabindex="-1">技能三：评估——判断结果对不对 <a class="header-anchor" href="#技能三-评估——判断结果对不对" aria-label="Permalink to &quot;技能三：评估——判断结果对不对&quot;">​</a></h2><p>&quot;测完了，怎么判断结果对不对？&quot; 这个问题比看上去难。因为你并不总有一个&quot;正确答案&quot;可以参考。</p><h3 id="四种判断结果的方法" tabindex="-1">四种判断结果的方法 <a class="header-anchor" href="#四种判断结果的方法" aria-label="Permalink to &quot;四种判断结果的方法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>怎么做</th><th>适合场景</th></tr></thead><tbody><tr><td><strong>需求文档</strong></td><td>对照 PRD 或验收标准</td><td>有明确书面需求时</td></tr><tr><td><strong>竞品对比</strong></td><td>同样场景下，竞品的行为是什么</td><td>需求模糊时，用行业标准来参照</td></tr><tr><td><strong>常识推断</strong></td><td>&quot;一个支付系统，总不能允许用户付负的钱吧？&quot;</td><td>基本逻辑校验</td></tr><tr><td><strong>一致性检查</strong></td><td>同一个操作在不同入口做，结果应该一致</td><td>发现不一致 = 发现了 bug</td></tr></tbody></table><h3 id="关注-绝不-和-始终" tabindex="-1">关注&quot;绝不&quot;和&quot;始终&quot; <a class="header-anchor" href="#关注-绝不-和-始终" aria-label="Permalink to &quot;关注&quot;绝不&quot;和&quot;始终&quot;&quot;">​</a></h3><p>Hendrickson 给了一条实用线索：<strong>任何文档或需求中出现的&quot;绝不&quot;和&quot;始终&quot;，就是你的测试靶心。</strong></p><ul><li>&quot;用户<strong>绝不</strong>能看到其他用户的订单&quot; → 试试各种越权访问方式</li><li>&quot;支付成功后<strong>始终</strong>会发送确认短信&quot; → 在各种异常场景下检查短信是否真的发了</li></ul><p>绝对化的表述 = 绝对的测试目标。专门盯着它测。</p><h2 id="技能四-改变维度——有意识地调整测试角度" tabindex="-1">技能四：改变维度——有意识地调整测试角度 <a class="header-anchor" href="#技能四-改变维度——有意识地调整测试角度" aria-label="Permalink to &quot;技能四：改变维度——有意识地调整测试角度&quot;">​</a></h2><p>当你对着一块功能测了半小时，觉得&quot;没什么好测的了&quot;——不是你测完了，而是你<strong>陷在同一个维度里了</strong>。</p><p>主动切换测试维度：</p><table tabindex="0"><thead><tr><th>维度</th><th>怎么切换</th><th>举例</th></tr></thead><tbody><tr><td><strong>交互</strong></td><td>换一种操作顺序</td><td>本来先填信息再提交 → 试试先提交再填信息</td></tr><tr><td><strong>顺序</strong></td><td>打乱操作的先后</td><td>正常的 A→B→C → 试试 C→B→A、B→A→C</td></tr><tr><td><strong>数据</strong></td><td>换一组数据</td><td>原本用正常数据 → 试试极端值、空值、重复值</td></tr><tr><td><strong>时间</strong></td><td>改变操作节奏</td><td>慢速操作 → 快速连续操作，中间打断它</td></tr><tr><td><strong>配置</strong></td><td>换环境</td><td>Chrome → Safari、WiFi → 4G、竖屏 → 横屏</td></tr></tbody></table><p><strong>一个简单但有效的技巧</strong>：每次你发现自己连续 10 分钟在同一个页面上做类似的操作，就主动换一个维度。不需要规划，强迫自己换一下就好。</p><h2 id="技能五-建模——画出系统的骨架" tabindex="-1">技能五：建模——画出系统的骨架 <a class="header-anchor" href="#技能五-建模——画出系统的骨架" aria-label="Permalink to &quot;技能五：建模——画出系统的骨架&quot;">​</a></h2><p>前面的技能帮你&quot;观察细节&quot;，建模帮你<strong>看清全局</strong>。</p><h3 id="状态模型" tabindex="-1">状态模型 <a class="header-anchor" href="#状态模型" aria-label="Permalink to &quot;状态模型&quot;">​</a></h3><p>把系统画成<strong>状态 + 转换</strong>的图。最适合订单、审批流、播放器等有明显状态的系统。</p><p><img src="'+i+'" alt="状态模型"></p><p>状态图出来后，测试策略自然涌现：</p><ul><li>正常路径：待支付→已支付→已发货→已完成</li><li>异常路径：每个状态能不能取消？已发货还能退款吗？</li><li>状态跳跃：有没有可能从&quot;待支付&quot;直接跳到&quot;已完成&quot;？</li></ul><h3 id="数据模型" tabindex="-1">数据模型 <a class="header-anchor" href="#数据模型" aria-label="Permalink to &quot;数据模型&quot;">​</a></h3><p>问三个问题：</p><ul><li><strong>实体</strong>是什么？（用户、订单、商品、评论）</li><li>每个实体的<strong>属性</strong>是什么？（订单有金额、状态、创建时间）</li><li>实体之间的<strong>依赖</strong>是什么？（一个订单必须关联一个用户和至少一个商品）</li></ul><p>然后沿着<strong>数据生命周期</strong>（CRUD：创建、读取、更新、删除）逐项测：</p><ul><li>创建订单后，数据库里真的多了一条记录吗？</li><li>删除用户后，他的历史订单怎么处理？</li><li>更新商品价格后，已生成但未支付的订单价格跟着变吗？</li></ul><h3 id="生态系统图" tabindex="-1">生态系统图 <a class="header-anchor" href="#生态系统图" aria-label="Permalink to &quot;生态系统图&quot;">​</a></h3><p>画出系统和外部世界的关系：</p><p><img src="'+e+'" alt="alt text"></p><p>关键问题：<strong>信任边界在哪？</strong> 你的系统信任支付网关返回的数据吗？如果支付网关返回了&quot;支付金额 = 0&quot;，你的系统会怎么做？</p><h2 id="实战场景一-探索-api-无-ui-界面" tabindex="-1">实战场景一：探索 API（无 UI 界面） <a class="header-anchor" href="#实战场景一-探索-api-无-ui-界面" aria-label="Permalink to &quot;实战场景一：探索 API（无 UI 界面）&quot;">​</a></h2><p>API、后端服务、微服务——这些没有图形界面的东西，探索式测试同样适用。你只是把&quot;眼睛&quot;从界面换成了工具。</p><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h3><ul><li><strong>curl / Postman</strong>：发 HTTP 请求</li><li><strong>日志 / 控制台</strong>：观察服务端行为</li><li><strong>数据库查询</strong>：确认数据是否写对</li></ul><h3 id="典型探索方向" tabindex="-1">典型探索方向 <a class="header-anchor" href="#典型探索方向" aria-label="Permalink to &quot;典型探索方向&quot;">​</a></h3><p>围绕一个 API 端点（比如 <code>POST /orders</code>）：</p><ul><li><strong>有效输入</strong>：正常参数，验证返回和数据库记录</li><li><strong>输入缺失</strong>：少传一个必填字段，返回什么？500 还是 400？</li><li><strong>类型错误</strong>：金额字段传了 <code>&quot;一百元&quot;</code> 而不是 <code>100</code>——解析崩溃还是友好报错？</li><li><strong>边界值</strong>：金额传 0、传负数、传一个天文数字</li><li><strong>并发</strong>：同一秒内发两个相同的请求，有没有幂等性问题？</li></ul><blockquote><p><a href="/testing/execution/bug-management.html">缺陷管理</a>讲的&quot;探索式测试中 Bug 报告是会话的自然产出&quot;在 API 场景中尤其明显——你在 Postman 里改参数、看响应、再改参数，这个过程中 Bug 报告就在形成了。</p></blockquote><h2 id="实战场景二-侦察遗留系统" tabindex="-1">实战场景二：侦察遗留系统 <a class="header-anchor" href="#实战场景二-侦察遗留系统" aria-label="Permalink to &quot;实战场景二：侦察遗留系统&quot;">​</a></h2><p>接手一个你没有参与开发的系统，没有文档，没有原班人马。探索式测试的&quot;侦察会话（Recon Session）&quot;就是为这个场景设计的。</p><h3 id="侦察会话" tabindex="-1">侦察会话 <a class="header-anchor" href="#侦察会话" aria-label="Permalink to &quot;侦察会话&quot;">​</a></h3><p>和普通测试会话的区别是——侦察的目标不是找 bug，而是<strong>建立对系统的理解</strong>。</p><p>章程示例：</p><blockquote><p>&quot;用正常用户操作和异常输入，探索订单模块的前后端交互，以理解数据流向和错误处理机制。&quot;</p></blockquote><h3 id="侦察中的具体做法" tabindex="-1">侦察中的具体做法 <a class="header-anchor" href="#侦察中的具体做法" aria-label="Permalink to &quot;侦察中的具体做法&quot;">​</a></h3><ol><li><strong>画图</strong>：边用边画生态系统图和状态图，不用漂亮，自己能看懂就行</li><li><strong>记录古怪现象</strong>：遇到任何你不理解的行为，记下来——&quot;为什么这里有两个相同的按钮？&quot;</li><li><strong>采访干系人</strong>：拿着你画出来的图去找还了解这个系统的人，&quot;我理解的数据流对吗？&quot;</li><li><strong>对不可重现的 Bug 保持敬畏</strong>：遗留系统中总有一些&quot;偶尔出现但无法稳定复现&quot;的问题——记录触发条件，不要轻易标记为&quot;无法复现就关掉&quot;</li></ol><h2 id="实战场景三-探索需求文档" tabindex="-1">实战场景三：探索需求文档 <a class="header-anchor" href="#实战场景三-探索需求文档" aria-label="Permalink to &quot;实战场景三：探索需求文档&quot;">​</a></h2><p>是的，需求文档也可以被&quot;测试&quot;。</p><h3 id="积极阅读-active-reading" tabindex="-1">积极阅读（Active Reading） <a class="header-anchor" href="#积极阅读-active-reading" aria-label="Permalink to &quot;积极阅读（Active Reading）&quot;">​</a></h3><p>不是在会上听产品经理讲需求时点头，而是<strong>在需求落地之前，用探索式测试的思维审视它</strong>。</p><ul><li>需求中哪些表述是模糊的？&quot;用户应该能够方便地找到想要的东西&quot;——什么叫&quot;方便&quot;？</li><li>需求中提到了哪些&quot;绝不&quot;和&quot;始终&quot;？拿小本本记下来</li><li>需求的某个场景，在极端情况下成立吗？&quot;用户下单后系统自动减库存&quot;——如果库存恰好为 0，且两个用户同时下单呢？</li></ul><h3 id="在需求会议前后写章程" tabindex="-1">在需求会议前后写章程 <a class="header-anchor" href="#在需求会议前后写章程" aria-label="Permalink to &quot;在需求会议前后写章程&quot;">​</a></h3><ul><li><strong>会前</strong>：根据你已知的信息，提前写好 3 个探测章程——&quot;如果我是测试，我会从哪几个方向挖&quot;</li><li><strong>会中</strong>：听到新信息，更新你的章程</li><li><strong>会后</strong>：把章程发给团队——&quot;这是我计划重点探索的方向，有遗漏吗？&quot;</li></ul><p>这样做的好处是：你不需要等开发做完才开始思考测试。<strong>测试从需求阶段就开始了。</strong></p><h2 id="结对探索-两个人的大脑比一个人好用" tabindex="-1">结对探索：两个人的大脑比一个人好用 <a class="header-anchor" href="#结对探索-两个人的大脑比一个人好用" aria-label="Permalink to &quot;结对探索：两个人的大脑比一个人好用&quot;">​</a></h2><p>有时候一个人单独探索容易陷入思维死角——你总是绕着同一个方向转。这时候拉一个同事组成<strong>结对探索（Pair Exploration）</strong>，效果往往翻倍。</p><p>和结队编程类似，两个人分工：</p><ul><li><strong>操作者</strong>：负责操作软件，讲解自己在做什么、看到了什么</li><li><strong>观察者</strong>：负责记录笔记、提出问题、指出操作者没注意到的细节</li></ul><p>半小时后交换角色。</p><p>结对探索的价值不只是&quot;多一双眼睛&quot;。操作者把思路说出来，本身就容易暴露自己的盲区——&quot;我在验证这个表单的各字段校验……等一下，我只测了必填字段，没测边界值&quot;——这个过程一个人闷头做的时侯不容易发生。</p><blockquote><p>不需要每次都结对，但在探索一个新系统、或者章程涉及高风险模块时，结对是一次低成本的风险对冲。</p></blockquote><h2 id="将探索式测试融入日常工作" tabindex="-1">将探索式测试融入日常工作 <a class="header-anchor" href="#将探索式测试融入日常工作" aria-label="Permalink to &quot;将探索式测试融入日常工作&quot;">​</a></h2><p>学了方法论和技能，最后一个问题是：<strong>怎么让探索式测试成为团队日常的一部分，而不是偶尔想起来才做一次？</strong></p><h3 id="探索和脚本测试怎么搭配" tabindex="-1">探索和脚本测试怎么搭配 <a class="header-anchor" href="#探索和脚本测试怎么搭配" aria-label="Permalink to &quot;探索和脚本测试怎么搭配&quot;">​</a></h3><p>不是二选一。Hendrickson 的建议是按迭代节奏分配：</p><table tabindex="0"><thead><tr><th>阶段</th><th>主要方式</th><th>探索式的位置</th></tr></thead><tbody><tr><td>新功能刚开发完</td><td>探索式为主</td><td>用章程快速挖掘风险和未预期行为</td></tr><tr><td>功能稳定后</td><td>脚本为主</td><td>把探索中发现的关键场景固化为自动化用例</td></tr><tr><td>每次回归之后</td><td>探索式补充</td><td>用 15~30 分钟快速探索，发现脚本盲区</td></tr><tr><td>大版本发布前</td><td>探索 + 脚本并重</td><td>全量回归 + 关键风险区域的深度探索</td></tr></tbody></table><p>简单说：<strong>探索打头阵、脚本守阵地。</strong> 探索负责&quot;发现&quot;——找到你没想到的问题；脚本负责&quot;守住&quot;——确保已知的问题不会复现。</p><h3 id="怎么估算工作量" tabindex="-1">怎么估算工作量 <a class="header-anchor" href="#怎么估算工作量" aria-label="Permalink to &quot;怎么估算工作量&quot;">​</a></h3><p>脚本测试比较好估算——有多少条用例、每条跑多久。探索式测试的估算靠的是经验法则：</p><ul><li>一个中等复杂度的功能模块，通常需要 3~5 个探测章程</li><li>每个章程一个会话（60~120 分钟），加上整理笔记，一个会话实际消耗约 2 小时</li><li>所以一个功能模块的探索投入 = <strong>3~5 个会话 × 2 小时 = 6~10 小时</strong></li></ul><p>新系统或高风险系统翻倍。记住这是一个经验起点，不是精确估算——测完两三个会话之后你对实际复杂度有了感觉，再调整。</p><h3 id="怎么向干系人汇报" tabindex="-1">怎么向干系人汇报 <a class="header-anchor" href="#怎么向干系人汇报" aria-label="Permalink to &quot;怎么向干系人汇报&quot;">​</a></h3><p>脚本测试的汇报方式大家熟悉——&quot;跑了 200 条用例，通过率 98%，发现 5 个 bug&quot;。探索式测试的汇报如果也这样说，就没体现它的价值。</p><p>探索式测试的汇报重点应该是：</p><ul><li><strong>覆盖了哪些区域</strong>：每个章程对应一个方向，&quot;我们重点探索了支付流程的幂等性、优惠券叠加计算、以及异常网络下的接口行为&quot;</li><li><strong>发现了什么风险</strong>：不只是 bug 列表，还包括&quot;这里的错误处理机制比较脆弱&quot;、&quot;这个模块的逻辑复杂度超出预期&quot;</li><li><strong>建议下一步做什么</strong>：&quot;建议下个迭代重点加强订单模块的错误处理&quot;、&quot;建议给搜索接口加输入长度限制&quot;</li></ul><blockquote><p>好的探索式测试汇报，让听众不只是知道&quot;测了多少&quot;，而是知道&quot;系统质量到底怎么样&quot;。</p></blockquote><h3 id="从单个-bug-到系统性发现" tabindex="-1">从单个 Bug 到系统性发现 <a class="header-anchor" href="#从单个-bug-到系统性发现" aria-label="Permalink to &quot;从单个 Bug 到系统性发现&quot;">​</a></h3><p>探索式测试最有价值的部分不是找到一堆零散的 bug，而是<strong>从多个探索会话中发现重复出现的模式</strong>，从而揭示系统性问题：</p><ul><li>连续三个会话都在表单校验上发现了问题 → 是不是团队的输入校验缺乏统一框架？</li><li>不同模块都出现了并发问题 → 是不是缺少通用的幂等性方案？</li><li>每次探索新模块都能找到 SQL 注入点 → 是不是 ORM 使用不规范？</li></ul><p>定期回顾多个会话的笔记，做一次&quot;跨会话分析&quot;，往往能找到比单个 bug 更有价值的改进方向。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>五个核心技能构成能力闭环：<strong>观察</strong>（看见行为）→ <strong>变量</strong>（找出变化）→ <strong>评估</strong>（判断对错）→ <strong>切换维度</strong>（换角度）→ <strong>建模</strong>（看全局）</li><li>提高可测试性——让不可见的行为可见，是测试人员的核心能力之一</li><li>API 探索、遗留系统侦察、需求文档探索——三类场景各有侧重，但都适用章程 + 会话 + 启发法的方法论</li><li><strong>结对探索</strong>是低成本的风险对冲——操作者边做边说、观察者记录提问，半小时换一次角色</li><li>探索式测试和脚本测试不是二选一：<strong>探索打头阵发现未知问题，脚本守阵地防止已知问题复现</strong></li><li>探索式汇报要跳出&quot;跑了几条用例&quot;的框架，重点是<strong>覆盖了什么方向、发现了什么风险、建议下一步做什么</strong></li><li>跨会话分析找模式——从多个会话的零散发现中提炼系统性问题，比修单个 bug 更有价值</li></ol>',103)])])}const b=o(n,[["render",s]]);export{c as __pageData,b as default};
